from (values
(1, 2, 'التفاعل الكيميائي إعادة ترتيب للذرات تنتج مواد جديدة.', '["الاتزان حالة تتساوى فيها سرعتا التفاعلين الأمامي والعكسي.","السرعة مقدار تغير التركيز مع الزمن.","","الذوبان تغير فيزيائي."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.668Z"}'::jsonb),
(2, 0, 'ذرات Al: 2 = 2، وذرات Br: 6 = 6، دون تغيير صيغ المواد.', '["","غيّر صيغة البروم إلى ذرات منفردة، وAl غير موزون.","غيّر صيغة الناتج.","غيّر صيغة الناتج، والوزن يكون بالمعاملات لا بتغيير الصيغ."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-29T09:32:29.668Z"}'::jsonb),
